import type { CSSObject } from '@emotion/react';
import emotionStyled from '@emotion/styled';

import { theme } from '../../../../theme';
import type { HeadingSize, TextAlignment } from './Heading';

interface StyledHeadingProps {
  $alignment: TextAlignment;
  $css?: CSSObject;
  $foreground: boolean;
  $selectable: boolean;
  $size: HeadingSize;
}

const headingStyles: Record<HeadingSize, CSSObject> = {
  Hero: {
    fontSize: theme.fonts.fontSizes['8'],
    lineHeight: theme.fonts.lineHeights['9'],
    '@media (min-width: 75rem)': {
      fontSize: theme.fonts.fontSizes['11'],
      lineHeight: theme.fonts.lineHeights['13'],
    },
  },
  H1: {
    fontSize: theme.fonts.fontSizes['6'],
    lineHeight: theme.fonts.lineHeights['7'],
    '@media (min-width: 37.5rem)': {
      fontSize: theme.fonts.fontSizes['7'],
      lineHeight: theme.fonts.lineHeights['8'],
    },
    '@media (min-width: 75rem)': {
      fontSize: theme.fonts.fontSizes['8'],
      lineHeight: theme.fonts.lineHeights['9'],
    },
  },
  H2: {
    fontSize: theme.fonts.fontSizes['5'],
    lineHeight: theme.fonts.lineHeights['6'],
    '@media (min-width: 37.5rem)': {
      fontSize: theme.fonts.fontSizes['6'],
      lineHeight: theme.fonts.lineHeights['7'],
    },
    '@media (min-width: 75rem)': {
      fontSize: theme.fonts.fontSizes['7'],
      lineHeight: theme.fonts.lineHeights['8'],
    },
  },
  H3: {
    fontSize: theme.fonts.fontSizes['5'],
    lineHeight: theme.fonts.lineHeights['6'],
    '@media (min-width: 75rem)': {
      fontSize: theme.fonts.fontSizes['6'],
      lineHeight: theme.fonts.lineHeights['7'],
    },
  },
  H4: {
    fontSize: theme.fonts.fontSizes['5'],
    lineHeight: theme.fonts.lineHeights['6'],
  },
  H5: {
    fontSize: theme.fonts.fontSizes['3'],
    lineHeight: theme.fonts.lineHeights['3'],
  },
};

export const StyledHeading = emotionStyled('h1', {
  shouldForwardProp: (propName) =>
    ![
      '$alignment',
      '$css',
      '$foreground',
      '$selectable',
      '$size',
      'as',
    ].includes(propName),
})<StyledHeadingProps>(
  ({ $alignment, $css, $foreground, $selectable, $size }) => ({
    color: $foreground
      ? theme.colors.interfaceForegroundLabelPrimary
      : theme.colors.interfaceLabelPrimary,
    fontFamily: theme.fonts.heading,
    fontWeight: theme.fonts.fontWeights.semibold,
    margin: 0,
    textAlign: $alignment,
    userSelect: $selectable ? 'auto' : 'none',
    '&::selection': $selectable
      ? {
          backgroundColor: 'rgb(from rgb(255, 255, 0) r g b / 40%)',
        }
      : undefined,
    ...headingStyles[$size],
    ...$css,
  }),
);
